const crypto = require('crypto');
const E = (e) => `${e.code ?? e.name} | ${String(e.message).split('\n')[0]}`;
const t = (l, f) => { try { console.log(l, '->', f()); } catch (e) { console.log(l, '-> THROW', E(e)); } };
t('randomBytes', () => [crypto.randomBytes(16).length, Buffer.isBuffer(crypto.randomBytes(0)), crypto.randomBytes(70000).length].join(','));
t('randomBytes dist', () => { const b = crypto.randomBytes(1 << 20); const c = new Array(256).fill(0); for (const x of b) c[x]++; const e = b.length / 256; const chi = c.reduce((s, o) => s + (o - e) ** 2 / e, 0); return chi > 150 && chi < 380 ? 'chi2 ok' : 'chi2 BAD ' + chi; });
t('randomBytes distinct', () => crypto.randomBytes(32).equals(crypto.randomBytes(32)));
t('randomBytes bad', () => crypto.randomBytes(-1));
t('randomUUID', () => { const u = crypto.randomUUID(); return [/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(u), new Set(Array.from({ length: 1000 }, () => crypto.randomUUID())).size].join(','); });
t('randomInt', () => { const c = [0, 0, 0, 0, 0, 0]; for (let i = 0; i < 60000; i++) c[crypto.randomInt(6)]++; return c.every((x) => x > 9400 && x < 10600) ? 'uniform ok' : 'BAD ' + c; });
t('randomInt range', () => { let mn = 1e9, mx = -1e9; for (let i = 0; i < 20000; i++) { const v = crypto.randomInt(-5, 5); mn = Math.min(mn, v); mx = Math.max(mx, v); } return [mn, mx].join(','); });
t('randomInt bad', () => crypto.randomInt(5, 5)); t('randomInt too large', () => crypto.randomInt(2 ** 48));
crypto.randomInt(10, (e, n) => console.log('randomInt cb ->', e, typeof n));
crypto.randomBytes(8, (e, b) => console.log('randomBytes cb ->', e, b.length));
t('randomFillSync', () => { const a = new Uint32Array(4); crypto.randomFillSync(a); return a.some((x) => x !== 0); });
t('getRandomValues', () => { const a = new Uint8Array(8); return [crypto.getRandomValues(a) === a, typeof crypto.webcrypto.getRandomValues].join(','); });
t('getRandomValues too big', () => crypto.getRandomValues(new Uint8Array(65537)));
t('getRandomValues float', () => crypto.getRandomValues(new Float32Array(2)));
t('webcrypto is platform', () => [crypto.webcrypto === globalThis.crypto, crypto.subtle === globalThis.crypto.subtle, typeof crypto.subtle.digest].join(','));
(async () => { const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode('abc')); console.log('subtle digest ->', Buffer.from(d).toString('hex')); })();
t('timingSafeEqual', () => [crypto.timingSafeEqual(Buffer.from('abc'), Buffer.from('abc')), crypto.timingSafeEqual(Buffer.from('abc'), Buffer.from('abd')), crypto.timingSafeEqual(new Uint16Array([1]), new Uint8Array([1, 0]))].join(','));
t('timingSafeEqual len', () => crypto.timingSafeEqual(Buffer.from('a'), Buffer.from('ab')));
t('timingSafeEqual str', () => crypto.timingSafeEqual('a', 'a'));
const k = crypto.createSecretKey(Buffer.from('00112233445566778899aabbccddeeff', 'hex'));
t('KeyObject', () => [k.type, k.symmetricKeySize, k.export().toString('hex'), JSON.stringify(k.export({ format: 'jwk' })), k instanceof crypto.KeyObject, k.equals(crypto.createSecretKey(Buffer.from('00112233445566778899aabbccddeeff', 'hex')))].join(' '));
t('KeyObject in cipher', () => { const c = crypto.createCipheriv('aes-128-cbc', k, Buffer.alloc(16)); return Buffer.concat([c.update('x'), c.final()]).toString('hex'); });
t('createSecretKey string enc', () => crypto.createSecretKey('abcd', 'hex').export().toString('hex'));
t('generateKeySync hmac', () => { const g = crypto.generateKeySync('hmac', { length: 128 }); return [g.type, g.symmetricKeySize].join(','); });
t('generateKeySync aes', () => crypto.generateKeySync('aes', { length: 256 }).symmetricKeySize);
for (const [n, f] of [['createSign', () => crypto.createSign('sha256')], ['createVerify', () => crypto.createVerify('sha256')], ['generateKeyPairSync', () => crypto.generateKeyPairSync('ed25519')], ['publicEncrypt', () => crypto.publicEncrypt('x', Buffer.from('a'))], ['privateDecrypt', () => crypto.privateDecrypt('x', Buffer.from('a'))], ['createECDH', () => crypto.createECDH('prime256v1')], ['diffieHellman', () => crypto.diffieHellman({})], ['createDiffieHellman', () => crypto.createDiffieHellman(512)], ['createPublicKey', () => crypto.createPublicKey('x')], ['createPrivateKey', () => crypto.createPrivateKey('x')], ['sign', () => crypto.sign('sha256', Buffer.from('a'), 'x')], ['getCurves', () => crypto.getCurves().length]]) t(`asym ${n}`, f);
try { crypto.generateKeyPair('ed25519', {}, (e) => console.log('asym generateKeyPair cb ->', e && E(e))); } catch (e) { console.log('asym generateKeyPair cb -> SYNC THROW', E(e)); }
t('constants', () => [crypto.constants.RSA_PKCS1_PADDING, crypto.constants.defaultCoreCipherList ? 'has' : 'no'].join(','));
t('getFips', () => crypto.getFips());
t('exports', () => Object.keys(crypto).sort().join(','));
